SELECT DISTINCT a.id, a.name
FROM architect a
JOIN bridge b ON a.id = b.architect_id;

SELECT a.id, a.name, ams.avg_built_year
FROM architect a
JOIN architect_mill_stats ams ON a.id = ams.architect_id;

SELECT id, name, location
FROM "bridge"
WHERE location LIKE '%United States%';

SELECT DISTINCT a.nationality1
FROM architect a
JOIN bridge b ON a.id = b.architect_id;
